urlset:
{%- for locale, files in i18n_alternates.items() %}
{%- for file in files %}
{%- if file.page and not file.page.is_link and 'noindex' not in file.page.meta.get('robots', '') %}

        {{ file.page.canonical_url | e }}
        {%- if file.page.update_date %}
        {{ file.page.update_date }}
        {%- endif %}
        {%- for language, alternate in file.alternates.items() %}
        {%- if not alternate.page or 'noindex' not in alternate.page.meta.get('robots', '') %}
        {%- set href = alternate.page.canonical_url if alternate.page and alternate.page.canonical_url else config.site_url ~ alternate.url %}

        {%- endif %}
        {%- endfor %}

{%- endif %}
{%- endfor %}
{%- endfor %}
